!doctype html>
<html lang="hi">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no">
<title>Lakadi Kaatne Wala</title>
<style>
*{box-sizing:border-box} body{margin:0;background:#9edbff;font-family:system-ui,sans-serif;overflow:hidden;touch-action:manipulation}
#game{height:100vh;display:flex;flex-direction:column;background:linear-gradient(#8ed7ff 0 58%,#77bd54 58% 100%)}
.top{display:flex;justify-content:space-around;gap:8px;padding:10px;background:#3b2415;color:#fff;font-weight:800}
.card{background:#5b351e;border-radius:12px;padding:7px 14px;text-align:center}.val{font-size:20px;color:#ffd65a}
.scene{position:relative;flex:1;overflow:hidden}.sun{position:absolute;right:25px;top:25px;width:70px;height:70px;background:#ffe56b;border-radius:50%}
.ground{position:absolute;bottom:0;width:100%;height:42%;background:#5c9f43}
.tree{position:absolute;left:50%;bottom:17%;transform:translateX(-50%);width:250px;height:330px}
.trunk{position:absolute;left:105px;bottom:0;width:55px;height:245px;background:#8b542d;border:6px solid #613719;border-radius:18px}
.cut{position:absolute;left:108px;bottom:205px;width:49px;height:55px;border-radius:50%;background:#e8b76b;border:5px solid #613719}
.leaf{position:absolute;background:#247a36;border:5px solid #185a29;border-radius:50%}.l1{width:145px;height:120px;left:15px;top:35px}.l2{width:150px;height:125px;left:100px;top:45px}.l3{width:150px;height:120px;left:55px;top:0}
#axe{position:absolute;right:8%;bottom:12%;font-size:90px;filter:drop-shadow(3px 5px 2px #333);transition:.12s;transform:rotate(-25deg)}
#axe.hit{transform:rotate(18deg) translate(-15px,-8px)}
.controls{background:#332015;padding:14px;text-align:center;color:white}.btn{border:0;border-radius:16px;background:#f3a51f;color:#3a210d;font-size:24px;font-weight:900;padding:14px 45px;box-shadow:0 5px #9b5f08}.btn:active{transform:translateY(4px);box-shadow:0 1px #9b5f08}
#msg{height:25px;font-weight:800;color:#ffe06a}
</style>
</head>
<body>
<div id="game">
<div class="top">
 <div class="card">🪵 Lakadi<br><span class="val" id="wood">0</span></div>
 <div class="card">🪙 Coins<br><span class="val" id="coins">0</span></div>
 <div class="card">🏆 Score<br><span class="val" id="score">0</span></div>
</div>
<div class="scene" id="scene">
 <div class="sun"></div><div class="ground"></div>
 <div class="tree">
  <div class="leaf l1"></div><div class="leaf l2"></div><div class="leaf l3"></div>
  <div class="trunk"></div><div class="cut"></div>
 </div>
 <div id="axe">🪓</div>
</div>
<div class="controls"><div id="msg">Ped ko kaatne ke liye button dabao!</div><br>
<button class="btn" id="cutBtn">🪓 LAKADI KAATO</button></div>
</div>
<script>
let wood=0,coins=0,score=0,hits=0;
const woodEl=document.querySelector('#wood'),coinsEl=document.querySelector('#coins'),scoreEl=document.querySelector('#score');
const axe=document.querySelector('#axe'), msg=document.querySelector('#msg'), btn=document.querySelector('#cutBtn');
btn.addEventListener('click',cut);
function cut(){
 hits++; wood++; score+=10; coins+=5;
 woodEl.textContent=wood; coinsEl.textContent=coins; scoreEl.textContent=score;
 axe.classList.remove('hit'); void axe.offsetWidth; axe.classList.add('hit');
 if(hits%10===0){msg.textContent='🔥 Wah! 10 cuts complete — bonus +25 coins!';coins+=25;coinsEl.textContent=coins}
 else msg.textContent='🪵 Chhatak! Lakadi mil gayi!';
 if(hits>=30){msg.textContent='🏆 Ped poora kaat diya! Naya ped aa gaya!';hits=0;wood+=5;coins+=50;woodEl.textContent=wood;coinsEl.textContent=coins}
}
</script>
</body></html>
